CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE ROLE service_role NOLOGIN BYPASSRLS;
GRANT USAGE ON SCHEMA public TO anon,authenticated,service_role;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT ALL ON TABLES TO anon,authenticated,service_role;
CREATE TABLE empresas(id uuid PRIMARY KEY);
CREATE TABLE utilizadores(id uuid PRIMARY KEY,empresa_id uuid REFERENCES empresas,funcao text,ativo boolean DEFAULT true);
CREATE TABLE colaboradores(id uuid PRIMARY KEY,empresa_id uuid REFERENCES empresas,nome text,data_admissao date,data_saida date);
CREATE TABLE medicina_trabalho(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),colaborador_id uuid NOT NULL REFERENCES colaboradores,data_ultima_consulta date,resultado text,data_proxima_consulta date,criado_em timestamptz NOT NULL DEFAULT now());
CREATE TABLE alertas(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid,tipo text,entidade_tipo text,entidade_id uuid,titulo text,descricao text,data_evento_referencia date,antecedencia_dias integer,data_gatilho date,destinatario_role text,estado text DEFAULT 'pendente',resolvido_por uuid,resolvido_em timestamptz,criado_em timestamptz DEFAULT now(),ocorrencia_chave uuid);
CREATE UNIQUE INDEX alertas_ocorrencia_unica_idx ON alertas(tipo,entidade_tipo,entidade_id,data_evento_referencia,coalesce(antecedencia_dias,-1),coalesce(ocorrencia_chave,'00000000-0000-0000-0000-000000000000'::uuid));
CREATE TABLE parametros_operacionais(chave text PRIMARY KEY,valor text);
CREATE TABLE documentos(id uuid PRIMARY KEY,empresa_id uuid,entidade_tipo text,entidade_id uuid,nome_arquivo text,tipo_documento text,data_validade date);
CREATE TABLE epis(id uuid PRIMARY KEY,colaborador_id uuid,tipo_epi text,data_validade date);
CREATE TABLE viaturas(id uuid PRIMARY KEY,empresa_id uuid,marca_modelo text,matricula text,data_inspecao_proxima date);
CREATE TABLE colaboradores_contratos(id uuid PRIMARY KEY,colaborador_id uuid,tipo_contrato text,data_fim_prevista date,estado text);
CREATE FUNCTION fn_utilizador_atual_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.actor',true),'')::uuid $$;
CREATE FUNCTION fn_e_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM utilizadores WHERE id=fn_utilizador_atual_id() AND ativo AND funcao IN('gerencia','gestao_plataforma')) $$;
CREATE FUNCTION fn_e_administrativo() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT fn_e_admin() OR EXISTS(SELECT 1 FROM utilizadores WHERE id=fn_utilizador_atual_id() AND ativo AND funcao='administrativo') $$;
CREATE FUNCTION fn_colaborador_na_obra_atual_encarregado(p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM utilizadores u JOIN colaboradores c ON c.empresa_id=u.empresa_id WHERE u.id=fn_utilizador_atual_id() AND u.ativo AND u.funcao='encarregado' AND c.id=p AND c.data_saida IS NULL AND c.nome='Visível ao Encarregado') $$;
CREATE FUNCTION fn_parametro_operacional_numero(p text,v numeric) RETURNS numeric LANGUAGE sql STABLE AS $$ SELECT coalesce((SELECT valor::numeric FROM parametros_operacionais WHERE chave=p),v) $$;
CREATE FUNCTION fn_parametro_operacional_dias(p text,v integer[]) RETURNS integer[] LANGUAGE sql STABLE AS $$ SELECT v $$;
ALTER TABLE medicina_trabalho ENABLE ROW LEVEL SECURITY;
CREATE POLICY pl_admin_total ON medicina_trabalho FOR ALL TO authenticated USING(fn_e_admin()) WITH CHECK(fn_e_admin());
CREATE POLICY pl_medicina_rh ON medicina_trabalho FOR ALL TO authenticated USING(fn_e_administrativo()) WITH CHECK(fn_e_administrativo());
CREATE POLICY pl_medicina_encarregado_atual_select ON medicina_trabalho FOR SELECT TO authenticated USING(fn_colaborador_na_obra_atual_encarregado(colaborador_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON medicina_trabalho TO authenticated;
GRANT SELECT ON utilizadores,colaboradores TO authenticated;
CREATE FUNCTION test_admissao(p uuid,d date) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO medicina_trabalho(colaborador_id,data_ultima_consulta,resultado) VALUES(p,d,'Consulta inicial registada na admissão') $$;
GRANT EXECUTE ON FUNCTION test_admissao(uuid,date) TO authenticated;
CREATE FUNCTION fn_verificar_congelamentos_pendentes() RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
CREATE FUNCTION fn_verificar_alertas_seguro_viaturas() RETURNS integer LANGUAGE sql AS $$ SELECT 0 $$;
CREATE FUNCTION fn_verificar_alertas_imoveis_orcamentos(date) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
CREATE FUNCTION fn_criar_lembretes_equipa_tecnica(date) RETURNS jsonb LANGUAGE sql AS $$ SELECT '{}'::jsonb $$;
